import pytest


@pytest.fixture(autouse=True)
def _reset_agentops_session():
    """Ensure no AgentOps session leaks between tests.

    Some tests use ``agentops.init(...)`` (which starts a session when
    ``auto_start_session=True``) and never explicitly call ``end_session``.
    Other tests rely on a clean singleton state and call
    ``agentops.start_session()`` themselves.  Without this fixture, the
    leftover session from a previous test breaks those later tests.
    """
    yield
    try:
        import agentops
        client = agentops.Client()
        if client is not None:
            try:
                session = getattr(client, "_session", None)
                if session is not None and not session.has_ended:
                    client.end_session(
                        end_state="Indeterminate",
                        end_state_reason="pytest fixture cleanup",
                    )
            except Exception:
                pass
    except Exception:
        pass

